def compute_frequencies(
    dump_dir: str,
    phase: str = "prefill",
    balanced: bool = False,
    file_list: list[str] | None = None,
    tail_tokens: int | None = None,
    max_new_tokens: int | None = None,
    records: list[dict] | None = None,
) -> dict[int, dict[int, float]]:
    """
    统计每层每个 expert 的激活频率。

    phase:          "prefill" 或 "decode"
    balanced:       True 时每个 request 平权（count / num_tokens），仅对 prefill 有效
    file_list:      要加载的文件名列表；None 表示加载 dump_dir 下所有 .json
    tail_tokens:    仅对 prefill 有效，只统计每条请求最后 N 个 token
    max_new_tokens: 仅对 decode 有效，只统计前 max_new_tokens-1 个 decode step
    records:        预加载的 JSON records；不为 None 时跳过磁盘读取
    """
    if records is None:
        records = load_records(dump_dir, file_list)

    freq: dict[int, dict[int, float]] = defaultdict(lambda: defaultdict(float))

    for record in records:
        if phase == "prefill":
            prefill = record.get("prefill", {})
            for layer_str, token_experts_list in prefill.items():
                lid = int(layer_str)
                if tail_tokens is not None:
                    token_experts_list = token_experts_list[-tail_tokens:]
                num_tokens = len(token_experts_list)
                weight = (1.0 / num_tokens) if (balanced and num_tokens > 0) else 1.0
                for experts in token_experts_list:
                    for eid in experts:
                        freq[lid][eid] += weight
        else:
            decode_steps = record.get("decode_steps", [])
            if max_new_tokens is not None:
                decode_steps = decode_steps[: max_new_tokens - 1]
            for step in decode_steps:
                for layer_str, experts in step.items():
                    lid = int(layer_str)
                    for eid in experts:
                        freq[lid][eid] += 1.0

    return freq

if strategy == "prefill_greedy":
    freq = compute_frequencies(dump_dir, phase="prefill", file_list=file_list,
                               records=records)
    return generate_greedy_placement(freq, ep_size)

if strategy == "prefill_last10_greedy":
    freq = compute_frequencies(dump_dir, phase="prefill", file_list=file_list,
                               tail_tokens=10, records=records)
    return generate_greedy_placement(freq, ep_size)
